# Setuplibrary(ggplot2)library(tidyverse)# Load the airquality datasetdata(airquality)# Basic summary of Temp and Wind variablessummary(airquality[c("Temp", "Wind")])# Create histogram with density plot for Temperatureggplot(airquality, aes(x = Temp)) +  geom_histogram(aes(y = ..density..), bins = 30, fill = "lightblue", color = "black") +  geom_density(color = "red") +  geom_vline(xintercept = median(airquality$Temp), color = "blue", linetype = "dashed") +  labs(title = "Temperature Distribution with Median",       x = "Temperature (°F)",       y = "Density") +  theme_minimal()# Create boxplot for Temperatureggplot(airquality, aes(y = Temp)) +  geom_boxplot(fill = "lightblue") +  labs(title = "Temperature Boxplot",       y = "Temperature (°F)") +  theme_minimal()# Calculate median and modetemp_median <- median(airquality$Temp)density_temp <- density(airquality$Temp)temp_mode <- density_temp$x[which.max(density_temp$y)]# Print the calculated valuescat("Temperature Median:", temp_median, "°F\n")cat("Temperature Mode (density peak):", round(temp_mode, 1), "°F\n")# Create side-by-side histograms with density plotspar(mfrow = c(1, 2))# Temperature distributionhist(airquality$Temp, prob = TRUE, main = "Temperature Distribution",     xlab = "Temperature (°F)", col = "lightblue", border = "black")lines(density(airquality$Temp), col = "red")# Wind distributionhist(airquality$Wind, prob = TRUE, main = "Wind Distribution",     xlab = "Wind Speed", col = "lightgreen", border = "black")lines(density(airquality$Wind), col = "red")# Reset plotting parameterspar(mfrow = c(1, 1))# Perform Shapiro-Wilk test for normalitytemp_shapiro <- shapiro.test(airquality$Temp)wind_shapiro <- shapiro.test(airquality$Wind)# Print test resultscat("\nShapiro-Wilk test for Temperature:\n")print(temp_shapiro)cat("\nShapiro-Wilk test for Wind:\n")print(wind_shapiro)# Calculate summary statistics for both variablestemp_summary <- c(  mean = mean(airquality$Temp),  sd = sd(airquality$Temp),  median = median(airquality$Temp),  IQR = IQR(airquality$Temp))wind_summary <- c(  mean = mean(airquality$Wind),  sd = sd(airquality$Wind),  median = median(airquality$Wind),  IQR = IQR(airquality$Wind))# Print summary statisticscat("\nTemperature Summary Statistics:\n")print(round(temp_summary, 2))cat("\nWind Summary Statistics:\n")print(round(wind_summary, 2))